export default function App() {
  const [tasks, setTasks] = useState<TaskItem[]>(INITIAL_TASKS);
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [taskToEdit, setTaskToEdit] = useState<TaskItem | null>(null);

  const handleDragStart = (_e: DragEvent, id: string) => {
    setDraggedTaskId(id);
  };

  const handleDragOver = (e: DragEvent) => {
    e.preventDefault();
  };

  const handleDrop = (_e: DragEvent, targetStatus: StatusType) => {
    if (!draggedTaskId) return;
    setTasks((prev) =>
      prev.map((t) => (t.id === draggedTaskId ? { ...t, status: targetStatus } : t))
    );
    setDraggedTaskId(null);
  };

  const handleMoveStatus = (id: string, newStatus: StatusType) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, status: newStatus } : t))
    );
  };

  const handleOpenAddModal = () => {
    setTaskToEdit(null);
    setIsModalOpen(true);
  };

  const handleOpenEditModal = (task: TaskItem) => {
    setTaskToEdit(task);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setTaskToEdit(null);
  };

  const handleSaveTask = (
    taskData: Omit<TaskItem, 'id' | 'createdAt'>,
    editId?: string
  ) => {
    if (editId) {
      setTasks((prev) =>
        prev.map((t) => (t.id === editId ? { ...t, ...taskData } : t))
      );
    } else {
      const newTask: TaskItem = {
        ...taskData,
        id: `task-${Date.now()}`,
        createdAt: new Date().toISOString().split('T')[0],
      };
      setTasks((prev) => [newTask, ...prev]);
    }
  };

  const handleDeleteTask = (id: string) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
  };

  const filteredTasks = tasks.filter((task) => {
    const matchesKeyword =
      task.title.toLowerCase().includes(searchKeyword.toLowerCase()) ||
      task.description.toLowerCase().includes(searchKeyword.toLowerCase()) ||
      task.assignee.toLowerCase().includes(searchKeyword.toLowerCase());

    const matchesPriority =
      priorityFilter === 'all' || task.priority === priorityFilter;

    return matchesKeyword && matchesPriority;
  });

  return (
    <div className="app-wrapper">
      <header className="app-header">
        <div className="header-title-group">
          <h1 className="header-title">カンバンボード</h1>
          <p className="header-subtitle">
            ドラッグ＆ドロップでタスク進捗を直感的に整理・管理できます
          </p>
        </div>

        <div className="header-actions">
          <div className="search-bar-container">
            <input
              type="text"
              className="search-input"
              placeholder="タイトル・説明・担当者を検索..."
              value={searchKeyword}
              onChange={(e) => setSearchKeyword(e.target.value)}
            />
          </div>

          <select
            className="priority-filter-select"
            value={priorityFilter}
            onChange={(e) => setPriorityFilter(e.target.value)}
          >
            <option value="all">すべての優先度</option>
            <option value="high">優先度: 高</option>
            <option value="medium">優先度: 中</option>
            <option value="low">優先度: 低</option>
          </select>

          <button
            type="button"
            className="btn-primary"
            onClick={handleOpenAddModal}
          >
            ＋ タスクを追加
          </button>
        </div>
      </header>

      <main className="board-container">
        <div className="board-columns">
          {COLUMNS.map((col) => (
            <KanbanColumn
              key={col.id}
              column={col}
              tasks={filteredTasks.filter((t) => t.status === col.id)}
              onDragStart={handleDragStart}
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onEditTask={handleOpenEditModal}
              onDeleteTask={handleDeleteTask}
              onMoveStatus={handleMoveStatus}
            />
          ))}
        </div>
      </main>

      <TaskModal
        isOpen={isModalOpen}
        taskToEdit={taskToEdit}
        onClose={handleCloseModal}
        onSave={handleSaveTask}
      />
    </div>
  );
}
